import fs from 'node:fs';
import path from 'node:path';
const root = process.cwd();
const out = path.join(root, 'output');
const read = file => JSON.parse(fs.readFileSync(path.join(root, file), 'utf8').replace(/^\uFEFF/, ''));
const write = (file, data) => fs.writeFileSync(path.join(out, file), JSON.stringify(data, null, 2) + '\n');
const observed = id => read(`input/artifacts/${id}/observed.json`);
const response = file => read(`output/${file}`);
const nearRank = (values, p) => { const sorted = [...values].sort((a,b) => a-b); return sorted[Math.max(0, Math.ceil(sorted.length*p)-1)]; };
const stat = values => ({count:values.length, sumMs:values.reduce((a,b)=>a+b,0), minMs:Math.min(...values), maxMs:Math.max(...values), meanMs:values.reduce((a,b)=>a+b,0)/values.length, p50Ms:nearRank(values,.5), p95Ms:nearRank(values,.95), p99Ms:nearRank(values,.99)});

const project = path.join(root, 'input/artifacts/l08/demo project');
const registryFile = path.join(project, '.workforce/development-launch.json');
const registry = JSON.parse(fs.readFileSync(registryFile, 'utf8').replace(/^\uFEFF/,''));
const packageJson = JSON.parse(fs.readFileSync(path.join(project, 'package.json'), 'utf8').replace(/^\uFEFF/,''));
const appDir = path.resolve(project, registry.applicationDirectory);
const appConfig = path.resolve(appDir, registry.applicationConfiguration);
const checkedPaths = [
  ['applicationDirectory', appDir],
  ['applicationConfiguration', appConfig],
  ['connectionScript', path.resolve(project,registry.connectionScript)],
  ['proxyScript', path.resolve(project,registry.proxyScript)],
  ['unifiedEntry', path.join(project,'Start-Development.ps1')]
].map(([field,target]) => ({field,path:path.relative(root,target).replaceAll('\\','/'),exists:fs.existsSync(target)}));
const entryContent = fs.readFileSync(path.join(project,'Start-Development.ps1'),'utf8').trim();
const connectionContent = fs.readFileSync(path.join(project,registry.connectionScript),'utf8').trim();
const appConfigParsed = JSON.parse(fs.readFileSync(appConfig,'utf8').replace(/^\uFEFF/,''));
const host = new URL(registry.applicationUrl);
const browser = new URL(registry.browserUrl);
const launch = {
  source:'input/artifacts/l08/demo project/.workforce/development-launch.json', registry, checkedPaths,
  resolutionRule:'登记路径按项目根目录解析；applicationConfiguration 按 applicationDirectory 解析。所有带空格路径均作为完整路径处理。',
  packageScripts:packageJson.scripts,
  unifiedEntry:'input/artifacts/l08/demo project/Start-Development.ps1',
  unifiedScriptPlaceholder:entryContent==='{}', connectionScriptPlaceholder:connectionContent==='{}', applicationConfigEmpty:Object.keys(appConfigParsed).length===0,
  applicationHost:{url:host.href,protocol:host.protocol,hostname:host.hostname,port:host.port},
  browserEntry:{url:browser.href,protocol:browser.protocol,hostname:browser.hostname,port:browser.port},
  conclusion:'不能直接确认可从统一入口启动：proxy.mjs 缺失；统一脚本和连接脚本都只有 {}，没有实际启动逻辑；应用配置为空。package.json 的 start/dev/preview/debug 虽都指向统一脚本，但不足以运行应用。',
  nextActions:['补齐登记引用的 proxy.mjs。','实现统一入口与连接脚本，并按应用契约补齐 application.json；路径解析要支持 tenant app 等含空格目录。','后续在授权启动时核验应用宿主 http://localhost:4870 与浏览器入口 https://localhost:9443 的联通及代理/TLS；本轮未启动任何服务。'],
  unresolved:['运行时依赖、端口、证书、代理转发、登录及真实页面均未验证。','材料未给出 application.json 字段契约，不能臆造其具体必填字段。']
};
write('l08-analysis.json',launch);

const samples = read('input/artifacts/l09/samples.json').samples;
const buckets = new Map();
for (const sample of samples) { const key=JSON.stringify([sample.scenario,sample.phase,sample.visibility]); if(!buckets.has(key))buckets.set(key,[]); buckets.get(key).push(sample); }
const groups = [...buckets.entries()].map(([key, rows]) => {
  const [scenario,phase,visibility] = JSON.parse(key);
  const success=rows.filter(x=>x.outcome==='success');
  const failures=rows.filter(x=>x.outcome!=='success');
  const beyond=rows.filter(x=>x.ms>x.budgetMs);
  return {scenario,phase,visibility,total:rows.length,successes:success.length,failures:failures.length,timeoutCount:rows.filter(x=>x.outcome==='timeout').length,failureRate:failures.length/rows.length,budgetMs:[...new Set(rows.map(x=>x.budgetMs))],overBudgetCount:beyond.length,successfulWithinBudgetCount:success.filter(x=>x.ms<=x.budgetMs).length,allAttemptLatency:stat(rows.map(x=>x.ms)),successOnlyLatency:stat(success.map(x=>x.ms)),observedAllAttemptsMeetBudget:failures.length===0&&beyond.length===0,p95MeetsTwoSecondBudget:nearRank(rows.map(x=>x.ms),.95)<=2000};
});
const performance={source:'input/artifacts/l09/samples.json',quantiles:'nearest-rank：升序第 ceil(p*n) 项；失败/超时也计入 allAttemptLatency。successOnlyLatency 单独列出，不能替代全部尝试。',total:samples.length,totalFailures:samples.filter(x=>x.outcome!=='success').length,groups,conclusion:'现有证据不能代表用户页面达标。前台 warm 的 p95 虽为 1140ms，但 20 次中有 1 次 9000ms 超时（5%失败）；前台 cold 唯一样本为3100ms，超过两秒预算；后台 warm 的20次700ms不能代替前台。材料未说明计时起止、渲染完成或可交互边界，也没有真实页面业务闭环证据。',followup:['分开补充冷启动和前台热启动样本，保留失败与超时；禁止将后台样本混入前台掩盖尾延迟。','先定位9000ms超时与冷启动3100ms的耗时来源，再按明确的用户可见起止事件复测。','总体成功率、尾延迟和用户端呈现需要共同验收；不能仅凭p95低于2000ms宣布全部达标。']};
write('l09-analysis.json',performance);

const task = read('input/artifacts/l10/task.json');
const history = read('input/artifacts/l10/history.json');
const events = history.records.map(r=>r.event).sort((a,b)=>a.seq-b.seq);
const current = events.filter(e=>e.seq>task.committedBeforeInput);
const calls = current.filter(e=>e.type==='tool/call');
const toolPairs = calls.map(call => { const result=current.find(e=>e.type==='tool/result'&&e.data.message?.toolCallId===call.data.callId); return {callSeq:call.seq,callId:call.data.callId,tool:call.data.name,resultSeq:result?.seq??null,isError:result?.data.message?.isError??null,resultText:result?.data.message?.content?.filter(c=>c.type==='text').map(c=>c.text).join('\n')??null}; });
const taskDiagnosis={task,historyHasMore:history.hasMore,committedBeforeInput:task.committedBeforeInput,excludedOldEndEvents:events.filter(e=>e.seq<=task.committedBeforeInput&&e.type==='turn/end'),currentEvents:current,toolPairs,currentTurnEndEvents:current.filter(e=>e.type==='turn/end'),assignmentVersionMismatch:task.assignmentVersion!==task.oldExecutionAssignmentVersion,conclusion:'本次更新原任务的工具调用失败，没有任务完成证据。seq102 call-update 对应 seq103 isError=true、task.execution_forbidden；seq104 的“已经处理完成”只是文字。seq88 completed 在边界100之前，不能作为本次完成回执。任务仍paused、归human-owner，当前assignmentVersion=8，旧执行=7。',concreteHandling:['维持原任务暂停和当前负责人；停止用旧assignmentVersion=7重复更新或恢复AI执行。','由当前负责人在原任务中核对实际工作并登记进度；此轮只读，未修改任务。','补齐hasMore所指的后续/剩余历史，重点核对边界100之后的匹配工具回执和turn/end；现有材料不足以确认当前轮是否终止。','只有今后获得恢复AI授权且当前归属、版本、状态和执行许可满足契约时，才考虑受管恢复；不创建替代任务掩盖失败。'],unresolved:['没有本轮成功的任务状态更新回执。','hasMore=true且当前窗口无turn/end，执行生命周期尚不能完整判断。','task.execution_forbidden 的精确服务端判定未提供；当前暂停、人工归属与版本不一致均须核实。']};
write('l10-analysis.json',taskDiagnosis);

const receipt = read('input/artifacts/l11/receipt.json');
const checks=[
  {field:'tenantId',expected:receipt.target.tenantId,actual:receipt.installation.tenantId},
  {field:'packageId',expected:receipt.target.packageId,actual:receipt.installation.packageId},
  {field:'target.operationId -> operation.id',expected:receipt.target.operationId,actual:receipt.operation.id},
  {field:'installation.latestOperationId -> operation.id',expected:receipt.installation.latestOperationId,actual:receipt.operation.id},
  {field:'operation.installationId -> installation.id',expected:receipt.installation.id,actual:receipt.operation.installationId},
  {field:'target.versionId -> operation.targetVersionId',expected:receipt.target.versionId,actual:receipt.operation.targetVersionId},
  {field:'target.versionId -> installation.installedVersionId',expected:receipt.target.versionId,actual:receipt.installation.installedVersionId}
].map(c=>({...c,match:c.expected===c.actual}));
const receiptDiagnosis={source:'input/artifacts/l11/receipt.json',checks,mismatches:checks.filter(c=>!c.match),reportedStatus:receipt.operation.status,canDeclareTenantLabComplete:false,conclusion:'不能宣布tenant-lab升级完成。安装属于tenant-other；成功操作是apo-unrelated，既不是目标apo-11，也不等于安装记录latestOperationId。包和目标版本相同、operation.installationId匹配并不能消除租户与操作关联错误。',concreteHandling:['在正确tenant-lab上下文按apg-11定位安装，并读取目标apo-11的最新操作详情。','核对tenantId、packageId、installationId、operationId、目标版本、安装revision和active/latest关联，再检查方案、冲突、绑定、确认和业务效果。','本轮仅诊断，不向错误租户继续、重试或执行升级。'],unresolved:['tenant-lab的真实安装状态、apo-11结果及业务可用性尚无证据。']};
write('l11-analysis.json',receiptDiagnosis);

const configuration = read('input/artifacts/l12/configuration.json');
const def = configuration.definitions.current;
const session = configuration.session;
const diffs=['agentId','workspace','preset','model'].map(field=>({field,currentDefinition:def[field],existingSession:session[field],matches:def[field]===session[field]}));
const configDiagnosis={source:'input/artifacts/l12/configuration.json',configuration,diffs,layers:[{layer:'skill发现与加载',evidence:{discovered:configuration.skillDiscovered,loaded:configuration.skillLoaded},diagnosis:'已发现且已加载；重复加载skill不能产生宿主命令工具。'},{layer:'执行宿主/工具注入',evidence:{nativeTools:configuration.nativeTools,businessTools:configuration.businessTools},diagnosis:'nativeTools为空，业务工具只有task_read。命令工具缺失应由宿主工具注册、允许集和会话能力配置排查，skill文字不能授权或注入。'},{layer:'员工定义与原会话快照',evidence:diffs,diagnosis:'同一agentId不表示旧会话自动应用新workspace/preset/model；原会话保持workspace-old、preset-old、model-a，定义已是new/new/model-b。'},{layer:'宿主重配置委托',evidence:configuration.hostObservation,diagnosis:'configureDelegate=false且原因为immutable_workspace_or_preset，原会话没有可用重配置入口；不能直接推断为模型不可用。'}],concreteHandling:['请维护者核对宿主支持的命令工具注册与既有授权配置；本轮不扩权、不新授工具。','核对目标员工定义的保存/发布与会话所绑定的workspace、preset、model，再确认产品是否支持保留会话的受管迁移。','若旧会话配置不可变，后续经用户选择可用当前定义建立新的会话，保留session-original及历史；本轮未创建、删除或重置会话。','不要以改skill、扩大权限、删除原会话或强改存储快照作为修复。'],unresolved:['没有宿主实现或运行时工具注册日志，无法确定为什么nativeTools为空。','没有支持原会话配置迁移的产品契约；不能声称已切换模型或恢复命令工具。']};
write('l12-analysis.json',configDiagnosis);

const rows=[];
const add=(caseId,method,apiPath,responseFile,bodyFile=null)=>rows.push({caseId,method,path:apiPath,bodyFile:bodyFile?`output/${bodyFile}`:null,responseFile:`output/${responseFile}`,status:response(responseFile).status});
for(const id of ['l01','l02','l03']){const n=Number(id.slice(1));add(id,'GET',`/api/application/v1/installations/api-${n}`,`${id}-installation-before.json`);add(id,'GET',`/api/application/v1/operations/apo-${n}`,`${id}-operation-before.json`);}
for(const id of ['l04','l05']){const n=Number(id.slice(1));add(id,'GET',`/api/application/v1/installations/api-${n}`,`${id}-installation-before.json`);add(id,'GET',`/api/application/v1/installations/api-${n}/components`,`${id}-components-before.json`);}
add('l06','GET','/api/xrain/v1/applications/app-orders/execution-authorization','l06-authorization-before.json');
add('l07','GET','/api/xrain/v1/applications/app-sales/publication-scope','l07-scope-before.json');
for(const [suffix,after] of [['','resolve'],['-corrected','correction'],['-composite','composite'],['-dotted','dotted'],['-record','record']]){
add('l01','POST','/api/application/v1/operations/apo-1/resolve',`l01-resolve${suffix}-response.json`,`l01-resolve${suffix}-body.json`);
add('l01','GET','/api/application/v1/operations/apo-1',`l01-operation-after-${after}.json`);add('l01','GET','/api/application/v1/installations/api-1',`l01-installation-after-${after}.json`);
}
add('l02','POST','/api/application/v1/operations/apo-2/retry','l02-retry-response.json','l02-retry-body.json');
add('l02','GET','/api/application/v1/installations/api-2','l02-installation-after-retry.json');
add('l02','GET','/api/application/v1/operations/apo-2','l02-original-operation-after-retry.json');
add('l02','GET','/api/application/v1/operations/l02-retry-apo-2','l02-retry-operation-after.json');
add('l03','POST','/api/application/v1/operations/apo-3/continue','l03-continue-response.json','l03-continue-body.json');
add('l03','GET','/api/application/v1/installations/api-3','l03-installation-after.json');
add('l03','GET','/api/application/v1/operations/apo-3','l03-operation-after.json');
add('l04','POST','/api/application/v1/installations/api-4/components/apr-view:restore','l04-restore-response.json','l04-restore-body.json');
add('l04','GET','/api/application/v1/installations/api-4','l04-installation-after.json');
add('l04','GET','/api/application/v1/installations/api-4/components','l04-components-after.json');
add('l05','DELETE','/api/application/v1/installations/api-5','l05-uninstall-response.json','l05-uninstall-body.json');
add('l05','GET','/api/application/v1/installations/api-5','l05-installation-after.json');
add('l05','GET','/api/application/v1/installations/api-5/components','l05-components-after.json');
add('l05','GET','/api/application/v1/operations/l05-uninstall-api-5','l05-uninstall-operation-after.json');
add('l06','PUT','/api/xrain/v1/applications/app-orders/execution-authorization/grants','l06-grants-response.json','l06-grants-body.json');
add('l06','GET','/api/xrain/v1/applications/app-orders/execution-authorization','l06-authorization-after.json');
add('l07','PUT','/api/xrain/v1/applications/app-sales/publication-scope','l07-scope-response.json','l07-scope-body.json');
add('l07','GET','/api/xrain/v1/applications/app-sales/publication-scope','l07-scope-after.json');
write('executed-requests.json',{note:'按案例组织的已执行请求索引，非跨案例时序；每次响应与请求体单独保存。未读取模拟器状态文件。',requests:rows});
write('l02-retry-link.json',{sourceOperationId:'apo-2',retryEndpoint:'/api/application/v1/operations/apo-2/retry',requestId:response('l02-retry-body.json').requestId,retryOperationId:response('l02-retry-response.json').data.id,installationId:'api-2',tenantId:'tenant-lab',packageId:'apg-2',targetVersionId:'apv-2',originalState:response('l02-original-operation-after-retry.json').data.status,retryState:response('l02-retry-operation-after.json').data.status,note:'关联由对原失败操作的retry调用及新旧操作回读证据保存；返回操作未提供独立parentOperationId字段。'});
console.log(JSON.stringify({launchMissing:checkedPaths.filter(x=>!x.exists),performanceGroups:groups,taskTools:toolPairs,receiptMismatches:checks.filter(x=>!x.match),configurationDifferences:diffs.filter(x=>!x.matches),savedRequestCount:rows.length},null,2));

